let sessionToken=null;
const publicServer='https://playform-studio-production.up.railway.app';
export function serverURL(project){const url=project?.backend?.url;return url?String(url).replace(/\/$/,''):location.hostname==='127.0.0.1'&&location.port==='14327'?publicServer:''}
export function validateServerURL(value){const url=new URL(value);if(url.username||url.password||url.search||url.hash||!['https:','http:'].includes(url.protocol)||url.protocol==='http:'&&!['localhost','127.0.0.1'].includes(url.hostname))throw Error('Use an HTTPS server URL, or localhost for testing.');return url.origin+url.pathname.replace(/\/$/,'')}
export async function backendFetch(path,options={},project){const base=serverURL(project),headers={...options.headers};if(sessionToken&&(!base||base===publicServer))headers.Authorization='Bearer '+sessionToken;return fetch(base+path,{...options,headers,credentials:base&&base!==location.origin?'omit':'same-origin'})}
export async function backendRequest(path,body,project){const response=await backendFetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)},project);const data=await response.json();if(!response.ok){const error=Error(data.error||'Server request failed.');error.code=data.code;error.status=response.status;throw error}return data}
export function openServerSettings(project,onSave=()=>{}){const d=document.createElement('dialog');d.className='editor-dialog server-settings';d.innerHTML='<div class="dialog-top"><h2>Server & account</h2><button id="close-server-settings" aria-label="Close server settings">×</button></div><p>Make unlimited games. This shared server can host or build your first project. Connect your own server for another project.</p><p id="server-account-status">Loading account…</p><details id="server-account-form"><summary>Sign in or create an account</summary><form><label>Username<input name="username" autocomplete="username" minlength="3" maxlength="32" required></label><label>Password<input name="password" type="password" autocomplete="current-password" minlength="10" maxlength="128" required></label><label>Action<select name="action"><option value="login">Sign in</option><option value="signup">Create account</option></select></label><button type="submit" class="primary">Continue</button></form></details><button id="server-signout" hidden>Sign out</button><h3>Your project server</h3><a href="/playform-server-kit.zip" download>Download server kit & setup instructions</a><label>Server URL<input id="project-server-url" type="url" placeholder="https://your-server.example.com"></label><p>Leave blank to use the shared service. Projects and single-player previews do not need a server.</p><div class="server-settings-actions"><button id="server-test">Test connection</button><button id="server-save" class="primary">Save connection</button></div><p id="server-connection-status" role="status"></p>';document.body.append(d);const $=s=>d.querySelector(s);$('#project-server-url').value=project?.backend?.url||(!project?localStorage.getItem('playform.serverDefault')||'':'');$('#close-server-settings').onclick=()=>d.close();async function refresh(){try{const response=await backendFetch('/api/account'),data=await response.json();$('#server-account-status').textContent=data.mode==='external'?'This server uses its own hosting.':data.user?'Signed in as '+data.user.username+'. '+(data.user.firstProject?'Your shared project is '+data.user.firstProject.name+'. Other projects need your own server.':'Your first-project allowance is unused.'):'Sign in when you want to use the shared service.';$('#server-signout').hidden=!data.user;$('#server-account-form').open=!data.user}catch{$('#server-account-status').textContent='The account service is not available.'}}$('#server-account-form form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const data=await backendRequest('/api/account',Object.fromEntries(new FormData(e.target)));sessionToken=data.sessionToken;await refresh();e.target.reset();$('#server-account-form').open=false}catch(error){$('#server-account-status').textContent=error.message}finally{button.disabled=false}};$('#server-signout').onclick=async()=>{await backendRequest('/api/account',{action:'logout'});sessionToken=null;refresh()};function candidate(){const value=$('#project-server-url').value.trim();return value?{...project,backend:{url:validateServerURL(value)}}:{...project,backend:null}}$('#server-test').onclick=async()=>{try{const next=candidate(),response=await backendFetch('/api/server-info',{},next);if(!response.ok)throw Error('Server did not respond.');const data=await response.json();if(data.application!=='playform')throw Error('This is not a compatible Playform server.');$('#server-connection-status').textContent='Connected. '+(data.mode==='shared'?'Shared service: first project only.':'Your own server is ready.')}catch(error){$('#server-connection-status').textContent=error.message}};$('#server-save').onclick=()=>{try{const next=candidate();if(project){project.backend=next.backend;onSave()}else{if(next.backend?.url)localStorage.setItem('playform.serverDefault',next.backend.url);else localStorage.removeItem('playform.serverDefault')}$('#server-connection-status').textContent=project?'Connection saved for this project.':'Default saved for new projects.'}catch(error){$('#server-connection-status').textContent=error.message}};d.onclose=()=>d.remove();refresh();d.showModal()}
